extends RefCounted
const BASE_ID := "creation-sandbox"
const BASE_VERSION := "1.0.0"
const Guard = preload("res://craftmine_shared/state_guard.gd")
const Contract = preload("res://scripts/scene_contract.gd")
const MeshPicker = preload("res://craftmine_shared/scene_mesh_picker.gd")
const ComponentState = preload("res://craftmine_shared/component_state.gd")
var component_state := ComponentState.new()
var component_capture_error := ""
var component_feedback_label: WeakRef
var component_feedback_original := ""
var component_feedback_text := ""
var component_feedback_until := 0

func world() -> Node:
	return Engine.get_main_loop().current_scene

func is_ready() -> bool:
	return world() != null and world().get("ready_for_play") == true

func bind_world(id: String) -> String:
	var pattern := RegEx.new()
	pattern.compile("^[a-z0-9][a-z0-9-]{1,47}$")
	var match_id := pattern.search(id)
	if match_id == null or match_id.get_string() != id:
		return "Invalid creation world ID"
	world().world_id = id
	return ""

func capture() -> Dictionary:
	var result: Dictionary = world().capture()
	var components := component_state.capture(world())
	component_capture_error = components.error
	if not component_capture_error.is_empty(): return {}
	if components.present: result["components"] = components.states
	return result

func capture_error() -> String:
	return component_capture_error

func interact_component() -> Dictionary:
	var found := component_state.nodes(world())
	if not found.error.is_empty(): return {"handled": true, "result": {"interacted": false, "reason": found.error}}
	if found.nodes.is_empty(): return {"handled": false}
	var player := world().get_node_or_null("Player")
	var camera := _target_camera()
	if player == null or camera == null: return {"handled": false}
	var hit := _ray_hit(camera, player, 4294967295)
	if hit.is_empty(): return {"handled": false}
	var owner := hit.collider as Node
	while owner != null and owner != world():
		if owner in found.nodes.values():
			if not owner.has_method("interact"): return {"handled": true, "result": {"interacted": false, "reason": "not-interactive"}}
			var result: Variant = owner.interact(player)
			if result is Dictionary and result.get("interacted") == true and result.get("feedback") is String:
				_show_component_feedback(result.feedback)
			return {"handled": true, "result": result if result is Dictionary else {"interacted": false, "reason": "invalid-component-interaction"}}
		owner = owner.get_parent()
	return {"handled": false}

func _show_component_feedback(message: String) -> void:
	var label: Variant = world().get("status_label")
	if not label is Label or not world().is_ancestor_of(label): return
	if component_feedback_label == null or component_feedback_label.get_ref() != label or label.text != component_feedback_text:
		component_feedback_original = label.text
	component_feedback_label = weakref(label)
	component_feedback_text = message.left(160)
	component_feedback_until = observed_physics_tick + 120
	label.text = component_feedback_text

func restore(body: Dictionary) -> String:
	var before := capture()
	if not component_capture_error.is_empty(): return component_capture_error
	var states: Variant = body.get("components", {})
	var failure: String = component_state.validate(world(), states)
	if not failure.is_empty(): return failure
	var native := body.duplicate(true)
	native.erase("components")
	failure = world().restore(native)
	if not failure.is_empty():
		return failure
	failure = component_state.restore(world(), states, body.has("components"))
	if not failure.is_empty():
		var rollback := before.duplicate(true)
		rollback.erase("components")
		var rollback_error: String = world().restore(rollback)
		return failure + ("; native rollback: " + rollback_error if not rollback_error.is_empty() else "")
	var missing := Guard.omitted(body, capture())
	if not missing.is_empty() or not component_capture_error.is_empty():
		var rollback := before.duplicate(true)
		rollback.erase("components")
		world().restore(rollback)
		component_state.restore(world(), before.get("components", {}), before.has("components"))
		return "Unsupported creation progress field: " + missing + component_capture_error
	return ""

var observed_physics_tick: int = 0
var scene_object_refs: Dictionary = {}
var observed_target_collider: int = 0
var mesh_picker := MeshPicker.new()

func _target_camera() -> Camera3D:
	var camera := world().get_viewport().get_camera_3d()
	return camera if camera != null and world().is_ancestor_of(camera) else null

func _ray_hit(camera: Camera3D, player: Node, mask: int) -> Dictionary:
	var excluded: Array[RID] = []
	if player is CollisionObject3D: excluded.append(player.get_rid())
	for child in player.find_children("*", "CollisionObject3D", true, false): excluded.append(child.get_rid())
	var center := camera.get_viewport().get_visible_rect().size * 0.5
	var direction := camera.project_ray_normal(center).normalized()
	var origin := camera.project_ray_origin(center) + direction * camera.near
	var query := PhysicsRayQueryParameters3D.create(origin, origin + direction * minf(80.0, camera.far - camera.near), mask, excluded)
	query.collide_with_areas = true
	return camera.get_world_3d().direct_space_state.intersect_ray(query)

func _helper_exclusions(player: Node, existing: Dictionary) -> Array[Node]:
	var excluded: Array[Node] = [player]
	# Existing base HUD references are excluded only when their actual native
	# geometry still has the narrow helper shape. No names/metadata grant exclusion.
	for field in ["marker", "selection_box"]:
		var node: Variant = world().get(field)
		if not node is MeshInstance3D or node.get_parent() != world() or node.get_script() != null or node.get_child_count() != 0 or node.mesh == null or node.mesh.get_script() != null: continue
		var material: Variant = node.material_override
		if not material is StandardMaterial3D or material.get_script() != null or material.shading_mode != BaseMaterial3D.SHADING_MODE_UNSHADED: continue
		if field == "marker" and node.mesh is SphereMesh and is_equal_approx(node.mesh.radius, 0.045) and is_equal_approx(node.mesh.height, 0.09): excluded.append(node)
		if field == "selection_box" and node.mesh is ImmediateMesh: excluded.append(node)
	# A current structured physics hit already establishes this entity. Other
	# visible entities remain in the mesh scan and may block an uncertain ray.
	if existing.get("surface") == "entity":
		for child in world().get_children():
			if str(child.name) == "Entity_" + str(existing.get("entityId", "")): excluded.append(child)
	return excluded

func _scene_node(node: Node) -> Dictionary:
	var script: Script = node.get_script() as Script
	return {"objectId": str(node.get_instance_id()), "nodePath": str(world().get_path_to(node)).left(513), "nodeClass": node.get_class().left(81), "scriptPath": script.resource_path.left(513) if script != null else "", "scenePath": node.scene_file_path.left(513)}

func _scene_ancestors(node: Node) -> Array:
	var result := []
	var ancestor := node.get_parent()
	while ancestor != null and ancestor != world() and result.size() < 4:
		result.append(_scene_node(ancestor))
		ancestor = ancestor.get_parent()
	return result

# Bounded read-only references from actual hits; project metadata is never identity.
func _scene_objects(existing: Dictionary) -> Dictionary:
	var camera := _target_camera()
	var player := world().get_node_or_null("Player")
	var selected: Variant = null
	var selection := {"status": "none", "reason": "no-current-camera"}
	if camera != null and player != null:
		var hit := _ray_hit(camera, player, 4294967295)
		var picked: Dictionary = mesh_picker.pick(world(), camera, _helper_exclusions(player, existing), hit)
		selection = {"status": picked.status, "reason": picked.reason, "counts": picked.counts}
		if picked.status == "fallback":
			hit = {}
		elif picked.status == "hit":
			var center := camera.get_viewport().get_visible_rect().size * 0.5
			var origin := camera.project_ray_origin(center) + camera.project_ray_normal(center).normalized() * camera.near
			# Physical interaction wins an exact surface tie. This is a precedence
			# rule, never a claim that a mesh and collider share object identity.
			if hit.is_empty() or origin.distance_to(picked.position) < origin.distance_to(hit.position) - MeshPicker.EPS:
				hit = {"collider": picked.node, "position": picked.position, "normal": picked.normal}
		if not hit.is_empty():
			var point: Vector3 = hit.position
			var collider := hit.collider as Node
			var stock_hit: bool = existing.get("surface") in ["ground", "entity", "boundary"] and collider != null and collider.get_instance_id() == observed_target_collider
			if not stock_hit and collider != null and world().is_ancestor_of(collider):
				var key := str(collider.get_instance_id())
				if not scene_object_refs.has(key):
					if scene_object_refs.size() >= 32: scene_object_refs.erase(scene_object_refs.keys()[0])
					scene_object_refs[key] = weakref(collider)
				selected = _scene_node(collider)
				selected["position"] = [point.x, point.y, point.z]
				selected["normal"] = [hit.normal.x, hit.normal.y, hit.normal.z]
				selected["ancestors"] = _scene_ancestors(collider)
	var live := []
	for key in scene_object_refs.keys():
		var node: Node = scene_object_refs[key].get_ref()
		if node == null or not node.is_inside_tree() or node.is_queued_for_deletion() or not world().is_ancestor_of(node):
			scene_object_refs.erase(key)
		else:
			var reference := _scene_node(node)
			reference["ancestors"] = _scene_ancestors(node)
			live.append(reference)
	return {"target": selected, "references": live, "selection": selection}

func _init() -> void:
	var tree := Engine.get_main_loop() as SceneTree
	if tree != null:
		tree.physics_frame.connect(_observe_physics_tick)

func _observe_physics_tick() -> void:
	var tree := Engine.get_main_loop() as SceneTree
	if tree != null and not tree.paused:
		observed_physics_tick += 1
		if component_feedback_label != null and observed_physics_tick >= component_feedback_until:
			var label: Variant = component_feedback_label.get_ref()
			# Never overwrite a later error or another system's HUD message.
			if is_instance_valid(label) and label.text == component_feedback_text:
				label.text = component_feedback_original
			component_feedback_label = null

func _actual_entity(node: Node3D, declared: Dictionary) -> Dictionary:
	var result := declared.duplicate(true)
	var position := node.global_position
	var scale := node.global_transform.basis.get_scale()
	result.position = [position.x, position.y, position.z]
	result.scale = [scale.x, scale.y, scale.z]
	result.rotationY = rad_to_deg(node.global_rotation.y)
	result.visible = false
	result.solid = false
	result.color = ""
	var mesh_bounds: Variant = null
	for child in node.find_children("*", "MeshInstance3D", true, false):
		var mesh_node := child as MeshInstance3D
		if mesh_node.mesh == null:
			continue
		if mesh_node.name == "CreationColorMesh":
			var material := mesh_node.get_active_material(0) as StandardMaterial3D
			if material != null:
				result.color = "#" + material.albedo_color.to_html(false)
		if not mesh_node.is_visible_in_tree():
			continue
		result.visible = true
		var bounds: AABB = mesh_node.global_transform * mesh_node.mesh.get_aabb()
		mesh_bounds = bounds if mesh_bounds == null else (mesh_bounds as AABB).merge(bounds)
	var blocking_bounds: Variant = null
	for child in node.find_children("*", "CollisionShape3D", true, false):
		var shape_node := child as CollisionShape3D
		var body := shape_node.get_parent() as PhysicsBody3D
		if body == null or not body.is_inside_tree() or body.process_mode == Node.PROCESS_MODE_DISABLED or body.collision_layer & 3 == 0 or shape_node.disabled or shape_node.shape == null:
			continue
		var shape_mesh := shape_node.shape.get_debug_mesh()
		if shape_mesh == null:
			continue
		result.solid = true
		var bounds: AABB = shape_node.global_transform * shape_mesh.get_aabb()
		blocking_bounds = bounds if blocking_bounds == null else (blocking_bounds as AABB).merge(bounds)
	if blocking_bounds != null:
		var bounds := blocking_bounds as AABB
		result["collisionBounds"] = {"min": [bounds.position.x, bounds.position.y, bounds.position.z], "max": [bounds.end.x, bounds.end.y, bounds.end.z]}
	if mesh_bounds != null:
		var bounds := mesh_bounds as AABB
		result["meshBounds"] = {"min": [bounds.position.x, bounds.position.y, bounds.position.z], "max": [bounds.end.x, bounds.end.y, bounds.end.z]}
	if declared.get("kind") == "door":
		var hinge := node.get_node_or_null("Hinge") as Node3D
		result.open = not result.solid and hinge != null and absf(hinge.rotation.y) >= PI / 3.0
	if declared.get("kind") == "chest":
		var lid := node.get_node_or_null("Lid") as Node3D
		result.opened = lid != null and lid.rotation.x < -0.1
	return result

func _actual_target(revision: int, actual: Array) -> Dictionary:
	observed_target_collider = 0
	var target := {"entityId": null, "position": null, "normal": null, "surface": "none", "revision": revision}
	var camera := _target_camera()
	var player := world().get_node_or_null("Player") as CollisionObject3D
	if camera == null or player == null:
		return target
	var hit := _ray_hit(camera, player, 7)
	if hit.is_empty():
		return target
	var point: Vector3 = hit.position
	var normal: Vector3 = hit.normal
	target.position = [point.x, point.y, point.z]
	target.normal = [normal.x, normal.y, normal.z]
	var collider := hit.collider as Node
	target.surface = collider.get_meta("surface", "none")
	var entity := collider
	while entity != null and entity.get_parent() != world():
		entity = entity.get_parent()
	if entity != null and str(entity.name).begins_with("Entity_"):
		var id := str(entity.name).trim_prefix("Entity_")
		for sampled in actual:
			if sampled.id != id:
				continue
			target.entityId = id
			target.surface = "entity"
			target.entityKind = sampled.kind
			target.entityName = sampled.get("parameters", {}).get("label", "") if sampled.kind == "marker" else {"tree":"树", "rock":"石头", "chest":"宝箱", "door":"门", "marker":"标记"}.get(sampled.kind, sampled.kind)
			target.scale = sampled.scale
			target.color = sampled.color
	if target.surface in ["ground", "entity", "boundary"]:
		observed_target_collider = collider.get_instance_id()
	return target

func observe() -> Dictionary:
	# Non-entity game data remains authored. Requirement entity facts are always
	# recomputed here by the core-pinned adapter, never trusted from this result.
	var result: Dictionary = world().observe()
	var document: Variant = JSON.parse_string(FileAccess.get_file_as_string("res://world/creation.json"))
	if not document is Dictionary or not document.get("entities") is Array:
		return {"error": "Creation observation source declaration unavailable"}
	var declared := {}
	var mutable_presence := {}
	for rule in document.get("rules", []):
		if rule is Dictionary and rule.get("kind") == "entity-behavior" and rule.get("entityIds") is Array:
			for id in rule.entityIds:
				mutable_presence[str(id)] = true
	for entry in document.entities:
		if entry is Dictionary and entry.get("id") is String:
			declared[entry.id] = entry
	var actual := []
	var obstacles := []
	for child in world().get_children():
		if not child is Node3D or not str(child.name).begins_with("Entity_"):
			continue
		var id := str(child.name).trim_prefix("Entity_")
		var definition: Dictionary = declared.get(id, {"id": id, "kind": "unknown", "parameters": {}})
		var sampled := _actual_entity(child as Node3D, definition)
		sampled["presenceMutable"] = mutable_presence.has(id)
		sampled["solidMutable"] = definition.get("kind") == "door"
		if sampled.has("collisionBounds"):
			obstacles.append({"entityId": id, "min": sampled.collisionBounds.min, "max": sampled.collisionBounds.max})
		actual.append(sampled)
	if not result.get("creation") is Dictionary:
		result.creation = {}
	result.creation.entities = actual
	result.creation.obstacles = obstacles
	result.creation.physicsTick = observed_physics_tick
	result.creation.revision = int(document.get("revision", 1))
	result.creation.target = _actual_target(result.creation.revision, actual)
	var scene_objects := _scene_objects(result.creation.target)
	result.creation.sceneObjectTarget = scene_objects.target
	result.creation.sceneObjectRefs = scene_objects.references
	result.creation.sceneObjectSelection = scene_objects.selection
	if scene_objects.selection.status == "fallback":
		result.creation.target = {"entityId": null, "position": null, "normal": null, "surface": "none", "revision": result.creation.revision}
	result.creation.timeOfDay = world().get("time_of_day")
	var inventory: Variant = world().get("inventory")
	result.inventory = inventory.duplicate(true) if inventory is Dictionary else {}
	var player := world().get_node_or_null("Player") as Node3D
	if player != null:
		if not result.get("player") is Dictionary:
			result.player = {}
		var position := player.global_position
		result.player.position = [position.x, position.y, position.z]
	return result

func command(op: String, args: Dictionary) -> Dictionary:
	var allowed := {"walk": ["forward", "right", "frames"], "wait": ["frames"], "look": ["yaw", "pitch"], "interact": [], "attack": [], "set-time": ["hours"]}
	if not allowed.has(op) or not Contract.fields(args, [], allowed[op]):
		return {"error": "Unsupported creation operation or argument"}
	if not is_ready():
		return {"error": "Creation world is not ready"}
	match op:
		"attack":
			var weapons: Array[Node] = []
			for node in world().get_tree().get_nodes_in_group("craftmine_player_weapons"):
				if world().is_ancestor_of(node) and not node.is_queued_for_deletion() and node.get("_player") == world().player:
					weapons.append(node)
			if weapons.size() != 1 or not weapons[0].has_method("attack"):
				return {"error": "Creation attack requires one configured player weapon"}
			var attacked: Variant = weapons[0].attack(world().player)
			return {"result": attacked} if attacked is Dictionary else {"error": "Invalid weapon result"}
		"walk", "wait":
			var frames: Variant = args.get("frames", 30 if op == "walk" else 1)
			if not Contract.integer(frames, 1, 600):
				return {"error": "Control requires 1..600 physics ticks"}
			if op == "walk":
				var forward: Variant = args.get("forward", 0)
				var right: Variant = args.get("right", 0)
				if not Contract.finite(forward, -1, 1) or not Contract.finite(right, -1, 1):
					return {"error": "Control axes must be finite -1..1"}
				await world().player.walk(Vector2(float(right), -float(forward)), int(frames))
			else:
				for _frame in int(frames):
					await world().get_tree().physics_frame
		"look":
			var pose: Dictionary = world().player.look()
			var yaw: Variant = args.get("yaw", pose.yaw)
			var pitch: Variant = args.get("pitch", pose.pitch)
			if not Contract.finite(yaw, -PI, PI) or not Contract.finite(pitch, -1.55, 1.55):
				return {"error": "Look angles must be bounded radians"}
			world().player.set_look(float(yaw), float(pitch))
		"interact":
			var component := interact_component()
			if component.handled: return {"result": component.result}
			return {"result": world().interact_target()}
		"set-time":
			if not args.has("hours") or not Contract.finite(args.hours, 0, 24):
				return {"error": "Time requires finite hours 0..24"}
			world().set_time(float(args.hours))
	return {"result": observe()}

extends RefCounted

const GROUP := "craftmine_persistent_components"
const MAX_COMPONENTS := 64
const MAX_STATE_BYTES := 65536
var retained: Dictionary = {}
var had_ledger := false
var fault := ""

static func live(root: Variant, node: Variant, id: String) -> bool:
	return is_instance_valid(root) and is_instance_valid(node) and node is Node and node.is_inside_tree() and root.is_ancestor_of(node) and not node.is_queued_for_deletion() and node.get("entity_id") == id

static func identifier(value: Variant) -> bool:
	if not value is String or value.is_empty() or value.length() > 128: return false
	var pattern := RegEx.new()
	pattern.compile("^[A-Za-z0-9][A-Za-z0-9._-]*$")
	var found := pattern.search(value)
	return found != null and found.get_string() == value

static func json_value(value: Variant, depth := 0) -> bool:
	if depth > 8: return false
	if value is Dictionary:
		if value.size() > 128: return false
		for key in value:
			if not key is String or key.length() > 128 or not json_value(value[key], depth + 1): return false
	elif value is Array:
		if value.size() > 1024: return false
		for item in value:
			if not json_value(item, depth + 1): return false
	elif value is float or value is int:
		return is_finite(float(value))
	elif value is String: return value.length() <= 4096
	elif value != null and not value is bool: return false
	return true

static func valid_state(id: String, state: Variant) -> bool:
	if not state is Dictionary or not json_value(state) or JSON.stringify(state).to_utf8_buffer().size() > MAX_STATE_BYTES: return false
	if state.get("entityId") != id or not state.get("format") is String or state.format.is_empty() or state.format.length() > 128: return false
	var settings: Variant = state.get("settings")
	var source: Variant = state.get("sourceSettings")
	if not settings is Dictionary or not source is Dictionary or source.size() > 16 or source.size() != settings.size(): return false
	for key in source:
		if not identifier(key) or not settings.has(key): return false
		if source[key] is Array or source[key] is Dictionary or settings[key] is Array or settings[key] is Dictionary: return false
		if typeof(source[key]) != typeof(settings[key]) and not ((source[key] is float or source[key] is int) and (settings[key] is float or settings[key] is int)): return false
	return true

func nodes(root: Node) -> Dictionary:
	var result := {}
	if not fault.is_empty(): return {"error": fault}
	if not is_instance_valid(root) or not root.is_inside_tree(): return {"error": "Component world is unavailable"}
	for node in root.get_tree().get_nodes_in_group(GROUP):
		if not root.is_ancestor_of(node): continue
		var id: Variant = node.get("entity_id")
		if not identifier(id) or result.has(id) or result.size() >= MAX_COMPONENTS or node.is_queued_for_deletion(): return {"error": "Invalid, duplicate or excessive component identity"}
		for method in ["snapshot", "validate_state", "restore"]:
			if not node.has_method(method): return {"error": "Component is missing " + method + ": " + id}
		result[id] = node
	return {"error": "", "nodes": result}

func capture(root: Node) -> Dictionary:
	var found := nodes(root)
	if not found.error.is_empty(): return found
	var states := retained.duplicate(true)
	for id in found.nodes:
		if not live(root, found.nodes[id], id): return {"error": "Component changed during capture: " + id}
		var state: Variant = found.nodes[id].snapshot()
		if not live(root, found.nodes[id], id): return {"error": "Component changed during snapshot: " + id}
		if not valid_state(id, state): return {"error": "Invalid component snapshot: " + id}
		# Match the actual JSON wire representation, not extra in-memory float
		# digits that Godot never writes. This is not a numeric error tolerance.
		state = JSON.parse_string(JSON.stringify(state))
		if states.has(id) and states[id].format != state.format: return {"error": "Component state format changed: " + id}
		var problem := _validate_node(root, found.nodes[id], id, state)
		if not problem.is_empty(): return {"error": "Component rejected its snapshot: " + id + ": " + problem}
		states[id] = state.duplicate(true)
	var after := nodes(root)
	if not after.error.is_empty() or after.nodes != found.nodes: return {"error": "Components changed during capture"}
	if states.size() > MAX_COMPONENTS: return {"error": "Component ledger exceeds limit"}
	retained = states.duplicate(true)
	had_ledger = had_ledger or not states.is_empty()
	return {"error": "", "states": states, "present": had_ledger or not states.is_empty()}

func _validate_node(root: Node, node: Variant, id: String, state: Dictionary) -> String:
	if not live(root, node, id): return "Component changed before validation"
	var before: Variant = node.snapshot()
	if not live(root, node, id) or not valid_state(id, before): return "Invalid live component snapshot"
	before = JSON.parse_string(JSON.stringify(before))
	var candidate := state.duplicate(true)
	var problem: Variant = node.validate_state(candidate)
	if not live(root, node, id):
		fault = "Component disappeared during validation: " + id
		return fault
	var after: Variant = node.snapshot()
	if not live(root, node, id):
		fault = "Component disappeared during validation snapshot: " + id
		return fault
	if not valid_state(id, after) or JSON.parse_string(JSON.stringify(after)) != before:
		var rollback: Variant = node.restore(before.duplicate(true))
		if not live(root, node, id) or rollback != "" or JSON.parse_string(JSON.stringify(node.snapshot())) != before:
			fault = "Validator changed live state; rollback failed: " + id
			return fault
		return "Validator changed live state"
	if candidate != state: return "Validator changed its input"
	return problem if problem is String else "Validator did not return a result"

func validate(root: Node, states: Variant) -> String:
	if not states is Dictionary or states.size() > MAX_COMPONENTS: return "Invalid component ledger"
	for id in states:
		if not identifier(id) or not valid_state(id, states[id]): return "Invalid saved component: " + str(id)
	var found := nodes(root)
	if not found.error.is_empty(): return found.error
	for id in found.nodes:
		if not states.has(id): return "Component default must be merged before restore: " + id
		var problem := _validate_node(root, found.nodes[id], id, states[id])
		if not problem.is_empty(): return "Component rejected saved state: " + id + ": " + problem
	return ""

# The adapter retains its native snapshot and rolls it back if this transaction
# fails. Every component is validated before any restore method is invoked.
func restore(root: Node, states: Dictionary, present: bool) -> String:
	var problem := validate(root, states)
	if not problem.is_empty(): return problem
	var before := capture(root)
	if not before.error.is_empty(): return before.error
	var found := nodes(root)
	if not found.error.is_empty(): return found.error
	for id in found.nodes:
		if not live(root, found.nodes[id], id):
			problem = "Component changed before restore: " + id
			break
		var result: Variant = found.nodes[id].restore(states[id].duplicate(true))
		if not live(root, found.nodes[id], id):
			problem = "Component changed during restore: " + id
			break
		if not result is String or not result.is_empty():
			problem = "Component restore failed: " + id + ": " + str(result)
			break
		var actual: Variant = found.nodes[id].snapshot()
		if not live(root, found.nodes[id], id) or not valid_state(id, actual) or JSON.parse_string(JSON.stringify(actual)) != JSON.parse_string(JSON.stringify(states[id])):
			problem = "Component restore did not preserve state: " + id
			break
	if problem.is_empty():
		for id in found.nodes:
			if not live(root, found.nodes[id], id):
				problem = "Component changed before restored validation: " + id
				break
			if found.nodes[id].has_method("validate_restored_state"):
				var result: Variant = found.nodes[id].validate_restored_state()
				if not result is String or not result.is_empty():
					problem = "Component rejected restored placement: " + id + ": " + str(result)
					break
			if not live(root, found.nodes[id], id):
				problem = "Component changed during restored validation: " + id
				break
	if problem.is_empty():
		for id in found.nodes:
			if not live(root, found.nodes[id], id):
				problem = "Component changed after restore: " + id
				break
			var actual: Variant = found.nodes[id].snapshot()
			if not live(root, found.nodes[id], id) or not valid_state(id, actual) or JSON.parse_string(JSON.stringify(actual)) != JSON.parse_string(JSON.stringify(states[id])):
				problem = "Component state changed after restore: " + id
				break
	var after := nodes(root)
	if not after.error.is_empty() or after.nodes != found.nodes: problem = "Components changed during restore"
	if not problem.is_empty():
		for id in found.nodes:
			if not live(root, found.nodes[id], id):
				fault = "Component rollback missing member: " + id
				problem += "; " + fault
				continue
			var node: Node = found.nodes[id]
			var rollback: Variant = node.restore(before.states[id].duplicate(true))
			if not live(root, node, id) or rollback != "" or JSON.parse_string(JSON.stringify(node.snapshot())) != before.states[id]:
				fault = "Component rollback failed: " + id
				problem += "; " + fault
		return problem
	retained = states.duplicate(true)
	had_ledger = present
	return ""

extends Node

# 示例源码：先操作第一个标记两次，再操作第二个标记开门。
# 这是可阅读和修改的普通脚本，不是 creation_operation 的新 action。
var _host: Node
var _door_id: String
var _first: String
var _second: String
var _presses := 0
var _completed := false

func configure(host: Node, definition: Dictionary) -> void:
	_host = host
	_door_id = definition.doorId
	_first = definition.sequence[0]
	_second = definition.sequence[1]

func on_entity_interacted(entity_id: String) -> void:
	if _completed:
		return
	if entity_id == _first:
		_presses = mini(_presses + 1, 2)
	elif entity_id == _second and _presses == 2:
		_completed = true
		_host.set_door_open(_door_id, true)
	else:
		_presses = 0

func snapshot() -> Dictionary:
	return {"presses": _presses, "completed": _completed}

func validate_state(data: Dictionary) -> String:
	if data.size() != 2 or not data.has("presses") or not data.has("completed"):
		return "Invalid double-press state fields"
	var presses: Variant = data.presses
	if not (presses is int or presses is float) or not is_finite(float(presses)) or float(presses) != floorf(float(presses)) or presses < 0 or presses > 2:
		return "Invalid double-press count"
	if not data.completed is bool or (data.completed and presses != 2):
		return "Invalid double-press completion"
	return ""

func restore(data: Dictionary) -> void:
	if not validate_state(data).is_empty():
		return
	_presses = int(data.presses)
	_completed = data.completed
	if _completed:
		_host.set_door_open(_door_id, true)
